import { createResponseError } from '../apiBase';
import { auth, isFirebaseReady } from '../../config/firebase';
import { getTrustedDeviceHeaders } from '../deviceTrustClient';

export const PROFILE_CACHE_TTL_MS = 15 * 1000;
export const PRODUCT_DETAIL_CACHE_TTL_MS = 30 * 1000;
export const AUTH_TOKEN_TIMEOUT_MS = 5 * 1000;

const getFirebaseIdToken = (user, forceRefresh, timeoutMs = AUTH_TOKEN_TIMEOUT_MS) => {
    const parsedTimeoutMs = Number(timeoutMs);
    const boundedTimeoutMs = Number.isFinite(parsedTimeoutMs) && parsedTimeoutMs > 0
        ? parsedTimeoutMs
        : AUTH_TOKEN_TIMEOUT_MS;
    let timeoutId;

    const timeoutPromise = new Promise((_, reject) => {
        timeoutId = setTimeout(() => {
            const error = new Error('Authentication session check timed out. Sign in again or use another account.');
            error.code = 'AUTH_TOKEN_TIMEOUT';
            reject(error);
        }, boundedTimeoutMs);
    });

    return Promise.race([
        Promise.resolve().then(() => user.getIdToken(forceRefresh)),
        timeoutPromise,
    ]).finally(() => clearTimeout(timeoutId));
};

/**
 * Returns trusted-device headers for steady-state API traffic.
 * Firebase bearer proof is attached for authenticated app traffic by default.
 * Cookie-only CSRF routes can opt out with { useFirebaseBearer: false }.
 */
export const getAuthHeader = async (firebaseUser = null, options = {}) => {
    const trustedDeviceHeaders = getTrustedDeviceHeaders();
    const hasExplicitBearerPreference = Object.prototype.hasOwnProperty.call(
        options || {},
        'useFirebaseBearer'
    );
    const shouldUseFirebaseBearer = options?.useFirebaseBearer === true
        || (!hasExplicitBearerPreference && Boolean(firebaseUser || auth?.currentUser));

    if (!shouldUseFirebaseBearer || !isFirebaseReady || !auth) {
        return trustedDeviceHeaders;
    }
    const user = firebaseUser || auth.currentUser;
    if (user) {
        const token = await getFirebaseIdToken(
            user,
            options?.forceRefresh === true,
            options?.tokenTimeoutMs
        );
        return {
            'Authorization': `Bearer ${token}`,
            ...trustedDeviceHeaders,
        };
    }
    return trustedDeviceHeaders;
};

/**
 * Parses API error responses into human-readable messages.
 */
export const parseApiError = async (response, fallbackMessage) => {
    const error = await createResponseError(response, fallbackMessage);
    return error.message;
};

/**
 * Creates an idempotency key for safe retries.
 */
export const createIdempotencyKey = (prefix = 'idmp') =>
    `${prefix}-${typeof crypto !== 'undefined' && crypto.randomUUID
        ? crypto.randomUUID()
        : `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`}`;

/**
 * Runs a callback during browser idle time or after a short delay.
 */
export const runWhenIdle = (callback) => {
    if (typeof window === 'undefined') return;
    if (typeof window.requestIdleCallback === 'function') {
        window.requestIdleCallback(callback, { timeout: 1500 });
        return;
    }
    window.setTimeout(callback, 250);
};
