import { initializeApp } from "firebase/app";
import {
    browserLocalPersistence,
    browserSessionPersistence,
    getAuth,
    GithubAuthProvider,
    GoogleAuthProvider,
    FacebookAuthProvider,
    OAuthProvider,
    setPersistence,
    TwitterAuthProvider,
} from "firebase/auth";
import { getAnalytics } from "firebase/analytics";
import { isCapacitorNativeRuntime } from "../utils/nativeRuntime";
import {
    HOSTED_DEPLOYMENT_HOST_SUFFIXES,
    PLANNED_CUSTOM_FRONTEND_HOSTS,
} from "../../config/hostedFrontendHosts.mjs";

const sanitizeFirebaseValue = (value) => {
    if (typeof value !== 'string') return value;
    return value
        .replace(/\\[rnt]/g, '')
        .replace(/[\r\n\t]+/g, '')
        .trim();
};

const parseFirebaseConfigEnv = (value) => {
    const sanitized = sanitizeFirebaseValue(value);
    if (!sanitized) return {};

    try {
        const parsed = JSON.parse(sanitized);
        return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
    } catch {
        return {};
    }
};

const aggregateFirebaseConfig = {
    ...parseFirebaseConfigEnv(import.meta.env.VITE_FIREBASE_CONFIG),
    ...parseFirebaseConfigEnv(import.meta.env.VITE_FIREBASE_WEB_CONFIG),
};

const getFirebaseConfigValue = (envKey, configKey, sanitizer = sanitizeFirebaseValue) => {
    const directValue = sanitizer(import.meta.env[envKey]);
    if (directValue) return directValue;
    return sanitizer(aggregateFirebaseConfig[configKey]);
};

const deriveDefaultAuthDomain = (projectId) => {
    const sanitizedProjectId = sanitizeFirebaseValue(projectId);
    if (!sanitizedProjectId || !/^[a-z0-9-]+$/i.test(sanitizedProjectId)) return undefined;
    return `${sanitizedProjectId}.firebaseapp.com`;
};

const isHostedDeploymentHost = (host = '') => {
    const normalizedHost = String(host || '').trim().toLowerCase();
    return PLANNED_CUSTOM_FRONTEND_HOSTS.includes(normalizedHost)
        || HOSTED_DEPLOYMENT_HOST_SUFFIXES.some((suffix) => normalizedHost.endsWith(suffix));
};

const sanitizeHostValue = (value) => {
    const normalized = sanitizeFirebaseValue(value);
    if (!normalized) return normalized;

    try {
        const url = new URL(normalized.includes('://') ? normalized : `https://${normalized}`);
        return url.hostname.trim();
    } catch {
        return normalized
            .replace(/^https?:\/\//i, '')
            .replace(/\/.*$/, '')
            .trim();
    }
};

const isIpv4Host = (host = '') => /^(?:\d{1,3}\.){3}\d{1,3}$/.test(host);

const isIpv6Host = (host = '') => {
    const normalized = sanitizeHostValue(host);
    return Boolean(
        normalized
        && !normalized.includes('.')
        && (normalized.includes(':') || normalized.startsWith('[') || normalized.endsWith(']'))
    );
};

const isIpLiteralHost = (host = '') => isIpv4Host(host) || isIpv6Host(host);

const parseBooleanEnv = (value, fallback = false) => {
    if (typeof value !== 'string') return fallback;
    const normalized = value.trim().toLowerCase();
    if (['true', '1', 'yes', 'on'].includes(normalized)) return true;
    if (['false', '0', 'no', 'off'].includes(normalized)) return false;
    return fallback;
};

const matchesDisplayMode = (mode = '') => {
    if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') {
        return false;
    }

    try {
        return Boolean(window.matchMedia(`(display-mode: ${mode})`)?.matches);
    } catch {
        return false;
    }
};

const isStandaloneSocialAuthRuntime = () => {
    if (typeof window === 'undefined') return false;

    const referrer = typeof document !== 'undefined' ? String(document.referrer || '').trim().toLowerCase() : '';

    return Boolean(
        matchesDisplayMode('standalone')
        || matchesDisplayMode('minimal-ui')
        || matchesDisplayMode('fullscreen')
        || matchesDisplayMode('window-controls-overlay')
        || window.navigator?.standalone === true
        || referrer.startsWith('android-app://')
    );
};

const isElectronDesktopRuntime = () => {
    if (typeof window === 'undefined') return false;
    if (window.auraDesktop?.isDesktop) return true;
    const userAgent = String(window.navigator?.userAgent || '');
    return /\bElectron\//i.test(userAgent);
};

export const firebaseConfig = {
    apiKey: getFirebaseConfigValue('VITE_FIREBASE_API_KEY', 'apiKey'),
    authDomain: getFirebaseConfigValue('VITE_FIREBASE_AUTH_DOMAIN', 'authDomain', sanitizeHostValue)
        || deriveDefaultAuthDomain(getFirebaseConfigValue('VITE_FIREBASE_PROJECT_ID', 'projectId')),
    projectId: getFirebaseConfigValue('VITE_FIREBASE_PROJECT_ID', 'projectId'),
    storageBucket: getFirebaseConfigValue('VITE_FIREBASE_STORAGE_BUCKET', 'storageBucket', sanitizeHostValue),
    messagingSenderId: getFirebaseConfigValue('VITE_FIREBASE_MESSAGING_SENDER_ID', 'messagingSenderId'),
    appId: getFirebaseConfigValue('VITE_FIREBASE_APP_ID', 'appId'),
    measurementId: getFirebaseConfigValue('VITE_FIREBASE_MEASUREMENT_ID', 'measurementId')
};

const requiredConfigKeys = [
    'apiKey',
    'authDomain',
    'projectId',
    'appId',
];

const hasRequiredConfig = requiredConfigKeys.every((key) => {
    const value = firebaseConfig[key];
    return typeof value === 'string' && value.trim().length > 0;
});

const buildFirebaseConfigError = (message) => {
    const error = new Error(message);
    error.code = 'auth/configuration-unavailable';
    return error;
};

let app = null;
let auth = null;
let googleProvider = null;
let facebookProvider = null;
let githubProvider = null;
let microsoftProvider = null;
let appleProvider = null;
let xProvider = null;
let analytics = null;
let firebaseInitError = null;

const runtimeHost = typeof window !== 'undefined'
    ? sanitizeHostValue(window.location.hostname || window.location.host)
    : '';
const disableSocialAuth = parseBooleanEnv(import.meta.env.VITE_FIREBASE_DISABLE_SOCIAL_AUTH, false);
const enableFirebaseAnalytics = parseBooleanEnv(import.meta.env.VITE_FIREBASE_ANALYTICS_ENABLED, false);
const forceRedirectSocialAuth = parseBooleanEnv(import.meta.env.VITE_FIREBASE_FORCE_REDIRECT_SOCIAL_AUTH, false);
const enableMicrosoftSocialAuth = parseBooleanEnv(import.meta.env.VITE_FIREBASE_ENABLE_MICROSOFT_AUTH, false);
const enableAppleSocialAuth = parseBooleanEnv(import.meta.env.VITE_FIREBASE_ENABLE_APPLE_AUTH, false);
const enableMobileNativeSocialAuth = parseBooleanEnv(
    import.meta.env.VITE_MOBILE_NATIVE_SOCIAL_AUTH_ENABLED,
    false
);
const enableMobileFirebasePhoneOtp = parseBooleanEnv(
    import.meta.env.VITE_MOBILE_FIREBASE_PHONE_OTP_ENABLED,
    false
);
const isDeploymentHost = typeof runtimeHost === 'string' && isHostedDeploymentHost(runtimeHost);
const isRuntimeIpHost = isIpLiteralHost(runtimeHost);
const isRuntimeStandaloneApp = isStandaloneSocialAuthRuntime();
const isRuntimeElectronDesktop = isElectronDesktopRuntime();
const isRuntimeCapacitorMobile = isCapacitorNativeRuntime();
const desktopRedirectSocialAuth = parseBooleanEnv(import.meta.env.VITE_FIREBASE_DESKTOP_REDIRECT_SOCIAL_AUTH, false);
const runtimeSocialAuthBlockKey = runtimeHost
    ? `aura-social-auth-block:${runtimeHost}`
    : 'aura-social-auth-block';
const runtimeSocialAuthBlockTtlMs = 2 * 60 * 1000;
const prefersRedirectSocialAuth = Boolean(
    forceRedirectSocialAuth
    || isRuntimeCapacitorMobile
    || (isRuntimeElectronDesktop && desktopRedirectSocialAuth)
    || (!isRuntimeElectronDesktop && (isRuntimeIpHost || isRuntimeStandaloneApp))
);

const isSocialAuthHostRejection = (error) => {
    const raw = `${error?.code || ''} ${error?.message || error || ''}`.toLowerCase();
    return (
        raw.includes('auth/unauthorized-domain')
        || raw.includes('illegal url for new iframe')
        || raw.includes('app url is not allowed in firebase authentication')
        || raw.includes('domain not authorized')
    );
};

const readRuntimeSocialAuthBlock = () => {
    if (typeof window === 'undefined') return false;
    try {
        const rawValue = window.sessionStorage.getItem(runtimeSocialAuthBlockKey);
        if (!rawValue) return false;

        // Clear legacy one-bit flags so old unauthorized-domain failures
        // do not keep social sign-in paused after the host is fixed.
        if (rawValue === '1') {
            window.sessionStorage.removeItem(runtimeSocialAuthBlockKey);
            return false;
        }

        const parsed = JSON.parse(rawValue);
        const blockedAt = Number(parsed?.blockedAt || 0);
        if (!blockedAt || (Date.now() - blockedAt) > runtimeSocialAuthBlockTtlMs) {
            window.sessionStorage.removeItem(runtimeSocialAuthBlockKey);
            return false;
        }

        return true;
    } catch {
        return false;
    }
};

if (!hasRequiredConfig) {
    firebaseInitError = buildFirebaseConfigError('Firebase configuration is missing required values.');
} else {
    try {
        app = initializeApp(firebaseConfig);
        auth = getAuth(app);
        // Web browsers keep Firebase tokens out of localStorage (XSS blast
        // radius); the Capacitor WebView is OS-sandboxed and loses
        // sessionStorage on cold start, so native keeps local persistence.
        setPersistence(auth, isRuntimeCapacitorMobile ? browserLocalPersistence : browserSessionPersistence).catch((error) => {
            console.warn('[firebase] unable to force auth persistence preference:', error?.message || error);
        });

        googleProvider = new GoogleAuthProvider();
        facebookProvider = new FacebookAuthProvider();
        githubProvider = new GithubAuthProvider();
        xProvider = new TwitterAuthProvider();
        microsoftProvider = enableMicrosoftSocialAuth ? new OAuthProvider('microsoft.com') : null;
        appleProvider = enableAppleSocialAuth ? new OAuthProvider('apple.com') : null;

        googleProvider.setCustomParameters({
            prompt: 'select_account',
        });

        facebookProvider.setCustomParameters({
            auth_type: 'rerequest',
            display: prefersRedirectSocialAuth ? 'page' : 'popup',
        });

        if (microsoftProvider) {
            microsoftProvider.setCustomParameters({
                prompt: 'select_account',
            });
        }

        if (appleProvider) {
            appleProvider.addScope('email');
            appleProvider.addScope('name');
        }

        if (typeof window !== 'undefined' && enableFirebaseAnalytics) {
            try {
                analytics = getAnalytics(app);
            } catch {
                analytics = null;
            }
        }
    } catch (error) {
        firebaseInitError = error;
        app = null;
        auth = null;
        googleProvider = null;
        facebookProvider = null;
        githubProvider = null;
        microsoftProvider = null;
        appleProvider = null;
        xProvider = null;
        analytics = null;
    }
}

export const isFirebaseReady = Boolean(app && auth);
export const isFirebaseSocialAuthAvailable = () => Boolean(
    isFirebaseReady
    && (!disableSocialAuth || isDeploymentHost)
    && (!isRuntimeCapacitorMobile || enableMobileNativeSocialAuth)
);
export const getFirebaseSocialAuthStatus = () => ({
    ready: isFirebaseReady,
    supported: isFirebaseSocialAuthAvailable(),
    runtimeHost,
    runtimeBlocked: readRuntimeSocialAuthBlock(),
    redirectPreferred: prefersRedirectSocialAuth || readRuntimeSocialAuthBlock(),
    runtimeIpHost: isRuntimeIpHost,
    runtimeStandaloneApp: isRuntimeStandaloneApp,
    runtimeElectronDesktop: isRuntimeElectronDesktop,
    runtimeCapacitorMobile: isRuntimeCapacitorMobile,
    mobileNativeSocialAuthEnabled: enableMobileNativeSocialAuth,
    mobileFirebasePhoneOtpEnabled: enableMobileFirebasePhoneOtp,
    microsoftEnabled: enableMicrosoftSocialAuth,
    appleEnabled: enableAppleSocialAuth,
    disabledByMobileNativeConfig: isRuntimeCapacitorMobile && !enableMobileNativeSocialAuth,
    mobilePhoneOtpDisabled: isRuntimeCapacitorMobile && !enableMobileFirebasePhoneOtp,
    disabledByConfig: disableSocialAuth && !isDeploymentHost,
    initErrorCode: firebaseInitError?.code || '',
    initErrorMessage: firebaseInitError?.message || '',
});
export const getFirebaseInitError = () => firebaseInitError;
export const shouldPreferFirebaseRedirectAuth = () => Boolean(
    prefersRedirectSocialAuth || readRuntimeSocialAuthBlock()
);
export const assertFirebaseReady = (feature = 'Firebase authentication') => {
    if (isFirebaseReady) return;

    if (firebaseInitError) {
        throw firebaseInitError;
    }

    throw buildFirebaseConfigError(`${feature} is not configured.`);
};

export const assertFirebaseSocialAuthReady = (feature = 'Social sign-in') => {
    assertFirebaseReady(feature);

    if (isRuntimeCapacitorMobile && !enableMobileNativeSocialAuth) {
        const error = buildFirebaseConfigError(
            `${feature} needs native mobile OAuth configuration before it can run in the installed app.`
        );
        error.code = 'auth/native-social-auth-configuration-missing';
        error.host = runtimeHost;
        throw error;
    }

    if (isFirebaseSocialAuthAvailable()) return;

    const error = buildFirebaseConfigError(`${feature} is disabled by deployment configuration.`);
    error.code = 'auth/social-auth-disabled';
    error.host = runtimeHost;
    throw error;
};

export const markFirebaseSocialAuthRejectedForRuntime = (error) => {
    if (typeof window === 'undefined' || !isSocialAuthHostRejection(error)) {
        return false;
    }

    try {
        window.sessionStorage.setItem(runtimeSocialAuthBlockKey, JSON.stringify({
            host: runtimeHost,
            blockedAt: Date.now(),
        }));
        return true;
    } catch {
        return false;
    }
};

export const clearFirebaseSocialAuthRuntimeBlock = () => {
    if (typeof window === 'undefined') return;
    try {
        window.sessionStorage.removeItem(runtimeSocialAuthBlockKey);
    } catch {
        // best-effort only
    }
};

export { app, auth, googleProvider, facebookProvider, githubProvider, microsoftProvider, appleProvider, xProvider, analytics };

export default app;
